WITH latest AS (SELECT id, channel, ends_on, discount_pct FROM promotions QUALIFY ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY starts_on DESC, id) = 1) SELECT id, channel, ends_on, discount_pct, CASE WHEN channel RLIKE '^(store|partner)$' THEN 'GROUP_A' WHEN channel RLIKE '^(web|mobile)$' THEN 'EXTENDED' ELSE 'CORE' END AS channel_zone FROM latest ORDER BY discount_pct NULLS FIRST;
